export type Cents = number;

export interface PayPeriod {
  start: string;
  end: string;
  workingDays: number;
}

export function roundCents(value: number): Cents {
  return Math.round(value);
}

export function prorate(amount: Cents, daysWorked: number, period: PayPeriod): Cents {
  if (daysWorked < 0 || daysWorked > period.workingDays) {
    throw new RangeError(`daysWorked ${daysWorked} outside 0..${period.workingDays}`);
  }
  return roundCents((amount * daysWorked) / period.workingDays);
}

export function applyBrackets(taxable: Cents, brackets: Array<{ upTo: Cents | null; rate: number }>): Cents {
  let remaining = taxable;
  let lower: Cents = 0;
  let tax = 0;
  for (const b of brackets) {
    if (remaining <= 0) break;
    const width = b.upTo === null ? remaining : Math.min(remaining, b.upTo - lower);
    tax += width * b.rate;
    remaining -= width;
    if (b.upTo !== null) lower = b.upTo;
  }
  return roundCents(tax);
}

import { Cents, PayPeriod, applyBrackets, prorate } from "./money";

export interface Employee {
  id: string;
  monthlySalary: Cents;
  pretaxDeductions: Cents;
  hireDate: string | null;
  terminationDate: string | null;
}

export interface Payslip {
  employeeId: string;
  gross: Cents;
  taxable: Cents;
  withholding: Cents;
  net: Cents;
}

const BRACKETS = [
  { upTo: 100_000, rate: 0.1 },
  { upTo: 400_000, rate: 0.22 },
  { upTo: null, rate: 0.32 },
];

function buildPayslip(employeeId: string, gross: Cents, pretax: Cents): Payslip {
  const taxable = Math.max(0, gross - pretax);
  const withholding = applyBrackets(taxable, BRACKETS);
  return { employeeId, gross, taxable, withholding, net: gross - pretax - withholding };
}

export function regularPayslip(e: Employee, period: PayPeriod): Payslip {
  return buildPayslip(e.id, e.monthlySalary, e.pretaxDeductions);
}

export function partialPeriodPayslip(e: Employee, period: PayPeriod, daysWorked: number): Payslip {
  const gross = prorate(e.monthlySalary, daysWorked, period);
  const pretax = prorate(e.pretaxDeductions, daysWorked, period);
  return buildPayslip(e.id, gross, pretax);
}

export function finalPayslip(
  e: Employee,
  period: PayPeriod,
  daysWorked: number,
  unusedLeavePayout: Cents,
): Payslip {
  const base = prorate(e.monthlySalary, daysWorked, period);
  const pretax = prorate(e.pretaxDeductions, daysWorked, period);
  return buildPayslip(e.id, base + unusedLeavePayout, pretax);
}

import { PayPeriod } from "./money";
import { Employee, Payslip, finalPayslip, partialPeriodPayslip, regularPayslip } from "./payslipCalculator";

export interface LeaveLedger {
  unusedLeaveCents(employeeId: string, asOf: string): Promise<number>;
}

function daysBetween(fromIso: string, toIso: string, period: PayPeriod): number {
  const ms = Date.parse(toIso) - Date.parse(fromIso);
  const calendar = Math.floor(ms / 86_400_000) + 1;
  return Math.max(0, Math.min(period.workingDays, Math.round((calendar * 5) / 7)));
}

export async function runPayroll(
  employees: Employee[],
  period: PayPeriod,
  leave: LeaveLedger,
): Promise<Payslip[]> {
  const slips: Payslip[] = [];
  for (const e of employees) {
    if (e.terminationDate && e.terminationDate >= period.start && e.terminationDate <= period.end) {
      const from = e.hireDate && e.hireDate > period.start ? e.hireDate : period.start;
      const days = daysBetween(from, e.terminationDate, period);
      const payout = await leave.unusedLeaveCents(e.id, e.terminationDate);
      slips.push(finalPayslip(e, period, days, payout));
    } else if (e.hireDate && e.hireDate > period.start && e.hireDate <= period.end) {
      slips.push(partialPeriodPayslip(e, period, daysBetween(e.hireDate, period.end, period)));
    } else if (!e.terminationDate || e.terminationDate > period.end) {
      slips.push(regularPayslip(e, period));
    }
  }
  return slips;
}
